#[cfg(test)]
mod tests {
    use std::path::PathBuf;

    fn owner() -> PathBuf {
        skein_scratch::paths::package()
    }

    #[test]
    fn current() {
        assert_eq!(skein_codegen::patch::current(&owner()), Ok(()), "run skein-codegen patch for this owner");
    }
}
